typedef struct {
    Screen& (*moveHome)(void);
    Screen& (*moveAbs)(int, int);
    Screen& (*moveRel)(int, int, const char*);
} ScreenOperations;

// Usage involves assigning function pointers to struct members and invoking them via struct instances.

code_example:
typedef struct Screen {
    ScreenOperations* ops;
    // other members
}
Screen& moveHomeImpl(void) { /* implementation */ }
Screen& moveAbsImpl(int x, int y) { /* implementation */ }
Screen& moveRelImpl(int dx, int dy, const char* direction) { /* implementation */ }

ScreenOperations screenOps = {
    .moveHome = moveHomeImpl,
    .moveAbs = moveAbsImpl,
    .moveRel = moveRelImpl
};

Screen screenInstance = {
    .ops = &screenOps
};

// Invoking functions via function pointers:
screenInstance.ops->moveHome();
screenInstance.ops->moveAbs(10, 20);
screenInstance.ops->moveRel(5, -5, "left");
